import { readFile } from "node:fs/promises";
import { createHash, randomUUID } from "node:crypto";
import assert from "node:assert/strict";
import { flowOwnerFixture } from "./campaign-flow-owner";
import { queueFixture } from "./campaign-control";
export const legacyWorkerRoot = "docs/specs/pipeline-os/campaign-send-recovery-20261118/";
export async function exerciseLegacyWorkerContext(f: Awaited<ReturnType<typeof flowOwnerFixture>>) {
  const { db } = f, account = f.accounts[0], job = randomUUID(), lease = randomUUID();
  await db.exec("reset role");
  // Structural doubles for only the account_id exclusion lookup; business tables/roles are real migrations.
  await db.exec("create schema if not exists mail_runtime;create table if not exists mail_runtime.routes(account_id uuid primary key);create schema if not exists simple_mail;create table if not exists simple_mail.health(account_id uuid primary key)");
  await db.exec("create schema if not exists mail_quota;create table mail_quota.head(id integer primary key,policy_id uuid,generation bigint,closed boolean);create table mail_quota.policies(policy_id uuid,generation bigint,policy jsonb);insert into mail_quota.head values(1,'00000000-0000-4000-8000-000000000001',1,false);insert into mail_quota.policies values('00000000-0000-4000-8000-000000000001',1,'{\"state\":\"enabled\"}')");
  const up = await readFile(legacyWorkerRoot + "up.sql", "utf8");
  await db.exec(up);
  await db.query("insert into mail_credentials(account_id,encrypted_refresh_token) values($1,'fixture-never-decrypted') on conflict do nothing", [account]);
  await db.query("insert into jobs(id,kind,payload,dedupe_key,status,locked_at,lease_token) values($1,'gmail_sending_usage',$2,$3,'running',now(),$4)", [job, { account_id: account }, randomUUID(), lease]);
  const service = () => db.exec("set role service_role");
  const read = async (a = account, j: string | null = job, l: string | null = lease, o: string | null = null, c: string | null = null) => {
    await service();
    return (await db.query<{ v: string | null }>("select legacy_worker_mail_context($1,$2,$3,$4,$5) v", [a, j, l, o, c])).rows[0].v;
  };
  const valid = await read();
  assert.match(valid!, /^[a-f0-9]{64}$/);
  assert.equal(await read(f.accounts[1]), null);
  assert.equal(await read(account, job, randomUUID()), null);
  assert.equal(await read(account, null, null), null);
  await db.exec("reset role;update mail_quota.head set closed=true");
  assert.equal(await read(), null);
  await db.exec("reset role;update mail_quota.head set closed=false");
  await db.exec("reset role");
  await db.query("update jobs set status='queued' where id=$1", [job]);
  assert.equal(await read(), null);
  await db.exec("reset role");
  await db.query("update jobs set status='running',locked_at=now()-interval '6 minutes' where id=$1", [job]);
  assert.equal(await read(), null);
  await db.exec("reset role");
  await db.query("update jobs set locked_at=now(),kind='import' where id=$1", [job]);
  assert.equal(await read(), null);
  await db.exec("reset role");
  await db.query("update jobs set kind='gmail_sending_usage' where id=$1", [job]);
  await db.query("insert into mail_runtime.routes(account_id) values($1)", [account]);
  assert.equal(await read(), null);
  await db.exec("reset role");
  await db.query("delete from mail_runtime.routes where account_id=$1", [account]);
  await db.query("insert into simple_mail.health(account_id) values($1)", [account]);
  assert.equal(await read(), null);
  await db.exec("reset role");
  await db.query("delete from simple_mail.health where account_id=$1", [account]);
  // A dispatch must prove its own durable sending row and current claim token.
  await f.asUser(f.users.admin);
  const launched = await f.launch({ ...f.p, scheduled_at: new Date().toISOString() });
  await queueFixture(f, launched.id);
  await db.exec("reset role");
  const outbox = (await db.query<any>("select id from outbox where account_id=$1 order by id limit 1", [account])).rows[0].id, claim = randomUUID();
  await db.query("update outbox set status='sending',sending_at=now(),brand_claim_token=$2 where id=$1", [outbox, claim]);
  assert.match((await read(account, null, null, outbox, claim))!, /^[a-f0-9]{64}$/);
  assert.equal(await read(account, null, null, outbox, randomUUID()), null);
  assert.equal(await read(account, job, lease, outbox, claim), null);
  await db.exec("reset role");
  await db.query("update outbox set sending_at=now()-interval '6 minutes' where id=$1", [outbox]);
  assert.equal(await read(account, null, null, outbox, claim), null);
  await db.exec("reset role");
  await db.query("update outbox set status='uncertain' where id=$1", [outbox]);
  assert.equal(await read(account, null, null, outbox, claim), null);
  assert.match((await read(account, null, null, outbox, null))!, /^[a-f0-9]{64}$/);
  await db.exec("reset role");
  await db.query("update mail_accounts set sync_enabled=not sync_enabled where id=$1", [account]);
  assert.notEqual(await read(), valid);
  await db.exec("reset role");
  await db.query("update mail_accounts set status='disconnected' where id=$1", [account]);
  assert.equal(await read(), null);
  await db.exec("reset role");
  await db.query("update mail_accounts set status='connected' where id=$1", [account]);
  await f.asUser(f.users.admin);
  await assert.rejects(db.query("select legacy_worker_mail_context($1,$2,$3)", [account, job, lease]), /permission denied/);
  await db.exec("reset role");
  const acl = (await db.query<any>("select has_function_privilege('anon','public.legacy_worker_mail_context(uuid,uuid,uuid,uuid,uuid)','execute') anon,has_function_privilege('authenticated','public.legacy_worker_mail_context(uuid,uuid,uuid,uuid,uuid)','execute') authenticated")).rows[0];
  assert.deepEqual(acl, { anon: false, authenticated: false });
  await db.exec(await readFile(legacyWorkerRoot + "down.sql", "utf8"));
  assert.equal((await db.query<any>("select to_regprocedure('public.legacy_worker_mail_context(uuid,uuid,uuid,uuid,uuid)') v")).rows[0].v, null);
  await db.exec(up);
  assert.match((await read())!, /^[a-f0-9]{64}$/);
  return { passed: true, permissions: true, expiredLeaseDenied: true, foreignAccountDenied: true, modernRouteDenied: true, modernHealthDenied: true, claimRequired: true, uncertainDenied: true, reversalPassed: true, sqlSha256: createHash("sha256").update(up).digest("hex"), realProviderRequests: 0 };
}
